    public static void main(String[] args) {
        new B().halo();
    }
}

interface A {
    default void halo() { System.out.println("Halo dari A"); }
}

class B implements A {
}

public class Main {
    public static void main(String[] args) {
        new B().halo();
    }
}

interface A {
    default void halo() { System.out.println("Halo dari A"); }
}

class B implements A {
    public void halo() { System.out.println("Halo dari B"); }
}

